const $=s=>document.querySelector(s);const roles=['Profissional de segurança','Pessoa física','Investigador institucional','Empresa'];let role=localStorage.getItem('nexo-role')||roles[0],page='Visão geral',paused=false,zoom=1,activeTool='Rede',project='Projeto Atlas';let evidence=[{name:'inventario_atlas.csv',desc:'Inventário de ativos · 3 ativos fictícios',type:'Inventário'},{name:'trafego_lab.pcap',desc:'Exemplo de captura · conteúdo não incluído',type:'Rede'}];const navs=[['◫','Visão geral'],['⌘','Terminal'],['⌁','Rede e ativos'],['◎','Mapa'],['⬡','Ferramentas'],['▤','Evidências'],['▧','Relatórios']];const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)};function modal(html){$('#modal').innerHTML='<section class="modal" role="dialog" aria-modal="true" aria-label="Configuração"><div class="modalhead"><span class="eyebrow">NEXO WORKSPACE</span><button onclick="closeModal()" aria-label="Fechar">✕</button></div>'+html+'</section>';$('#modal').hidden=false;$('#modal button').focus()}function closeModal(){$('#modal').hidden=true}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};function profiles(){modal('<h1>Seu ambiente. Sua missão.</h1><p class="sub">Escolha um perfil para explorar a experiência. A seleção é demonstrativa e não verifica credenciais.</p><div class="profiles">'+roles.map((r,i)=>'<button class="profilecard" onclick="selectRole('+i+')"><span>'+['⌘','◇','◎','▦'][i]+'</span><strong>'+r+'</strong><p>'+['Ferramentas, terminal e investigação em um só lugar.','Orientação clara para proteger sua vida digital.','Casos, evidências e pistas organizadas.','Uma visão simples da segurança da organização.'][i]+'</p></button>').join('')+'</div>')}function selectRole(i){role=roles[i];localStorage.setItem('nexo-role',role);page='Visão geral';closeModal();render();toast('Ambiente adaptado para '+role)}$('#profileBtn').onclick=toggleAccountMenu;$('#help').onclick=()=>{modal('<h1>Explore o primeiro NEXO</h1><p class="sub">Troque de perfil no canto inferior esquerdo. No laboratório, selecione pontos do mapa, experimente os comandos help, whoami e ip -br a, organize evidências e baixe um relatório.</p><p class="sub">Esta versão não executa ferramentas, não pesquisa a internet e não envia dados a uma IA. As respostas do assistente são roteiros locais. Nenhum arquivo é enviado a um servidor.</p><button class="primary" onclick="closeModal()">Entendi</button>')};function go(p){page=p;render()}function render(){if(localStorage.getItem('nexo-signed-out')==='true'){showLogin();return}document.body.classList.remove('signed-out');$('#loginScreen').hidden=true;const pro=role===roles[0];$('#roleLabel').textContent=role;$('#crumb').textContent=page;$('#nav').innerHTML=(pro?navs:[['◫','Visão geral'],['▤','Evidências'],['▧','Relatórios']]).map(([i,n])=>'<button class="'+(page===n?'active':'')+'" onclick="go(\''+n+'\')"><span>'+i+'</span><span class="navtext">'+n+'</span></button>').join('');$('#content').innerHTML=pro?lab():simple();bind();if(typeof initGlobe==='function')initGlobe();}function title(name,sub){return '<div class="titlebar"><div><div class="eyebrow">INTELIGÊNCIA CONECTADA</div><h1>'+name+'</h1><p class="sub">'+sub+'</p></div><div class="titleactions"><span class="badge">● '+(paused?'Ambiente pausado':'Modo demonstração')+'</span><button onclick="setup()">＋ Novo ambiente</button></div></div>'}function stats(){return '<div class="stats">'+[['Ativos no escopo','03','Ambiente fictício','⌁','green'],['Evidências do caso',String(evidence.length).padStart(2,'0'),'Organizadas neste navegador','▤',''],['Ferramentas disponíveis','08','Catálogo de demonstração','⬡','purple'],['Status do ambiente',paused?'Pausado':'Pronto','Nenhuma execução real','◉','green']].map(([l,v,s,i,c])=>'<div class="stat"><label>'+l+'</label><span class="symbol">'+i+'</span><strong class="'+c+'">'+v+'</strong><small>'+s+'</small></div>').join('')+'</div>'}function tools(){const data={Rede:[['⌁','Nmap','Descoberta de ativos'],['◈','Wireshark','Análise de tráfego']],OSINT:[['◎','Sherlock','Pesquisa de perfis públicos'],['◇','Metadados','Correlação de informações']],Arquivos:[['▤','Inspeção de arquivos','Formato e metadados'],['#','Hash SHA-256','Identificação de arquivos']],Web:[['⊞','Cabeçalhos HTTP','Revisão de configuração'],['▧','Certificados TLS','Inspeção de certificados']]};return '<section class="card"><div class="cardhead"><h2>Ferramentas</h2><span class="pill">CATÁLOGO</span></div><div class="tabs">'+Object.keys(data).map(x=>'<button class="'+(activeTool===x?'selected':'')+'" onclick="activeTool=\''+x+'\';render()">'+x+'</button>').join('')+'</div>'+data[activeTool].map(([i,n,d])=>'<button class="tool" onclick="toolInfo(\''+n+'\')"><span class="toolicon">'+i+'</span><span><strong>'+n+'</strong><small>'+d+'</small></span><span class="run">↗</span></button>').join('')+'<div class="toolfoot">◎ Execução real ainda não conectada</div></section>'}function toolInfo(n){modal('<h1>'+esc(n)+'</h1><p class="sub">Este módulo faz parte do catálogo planejado. Na versão operacional, sua execução acontecerá em um ambiente isolado, com escopo e permissões definidos.</p><p class="sub">Nesta demonstração você pode conhecer o fluxo sem instalar ou executar a ferramenta.</p><button class="primary" onclick="closeModal();askPreset(\'Explique '+esc(n)+'\')">Perguntar ao assistente</button>')}function investigationMapCard(){let minor='',roads='';for(let x=-200;x<1000;x+=45)minor+='<path d="M'+x+' 0 l170 400 M0 '+(x/2)+' l900 150"/>';for(let x=-100;x<900;x+=170)roads+='<path d="M'+x+' 0 l100 400"/>';return '<section class="card"><div class="cardhead"><h2>Mapa da investigação</h2><small>ATLAS / FICTÍCIO</small></div><div class="map"><svg id="mapsvg" viewBox="0 0 700 340" aria-label="Mapa ilustrativo com três pontos selecionáveis"><rect width="700" height="340" fill="#111e2a"/><g class="minor">'+minor+'</g><path class="park" d="M480 10h150l-40 90-100-30zM25 235l130 20-30 80H15z"/><path class="water" d="M310 -10C410 80 180 180 350 350H400C230 170 470 80 360 -10Z"/><g class="roads">'+roads+'<path d="M0 100L700 220M0 250L700 80M100 0L600 340"/></g><g class="maplabel"><text x="90" y="65">VILA NORTE</text><text x="430" y="70">JARDIM ATLAS</text><text x="150" y="195">CENTRO</text><text x="470" y="290">CIDADE NOVA</text></g>'+[[220,140,'Servidor Atlas',0],[430,180,'Estação de análise',1],[520,90,'Evidência documental',2]].map(([x,y,n,i])=>'<g class="marker" tabindex="0" role="button" aria-label="'+n+'" onclick="selectPin('+i+')" onkeydown="if(event.key===\'Enter\')selectPin('+i+')"><circle cx="'+x+'" cy="'+y+'" r="23" fill="'+(i===2?'#a18bff':'#55e6d5')+'" opacity=".1"/><circle cx="'+x+'" cy="'+y+'" r="9" fill="'+(i===2?'#a18bff':'#55e6d5')+'" stroke="#d3fff8" stroke-width="2"/></g>').join('')+'</svg><div class="mapcontrols"><button onclick="mapZoom(.2)" aria-label="Ampliar mapa">+</button><button onclick="mapZoom(-.2)" aria-label="Reduzir mapa">−</button></div><div class="mapinfo" id="mapinfo">Servidor Atlas<small>Origem: inventário fictício</small><small>Localização ilustrativa</small></div><div class="mapcaption">MAPA ILUSTRATIVO · SEM GEOLOCALIZAÇÃO REAL</div></div><div class="maplegend"><span>● Ativos</span><span>● Evidências</span><span>◎ Posições aproximadas</span></div></section>'}function selectPin(i){$('#mapinfo').innerHTML=['Servidor Atlas<small>Origem: inventário fictício</small><small>Ativo: 10.10.0.10</small>','Estação de análise<small>Origem: inventário fictício</small><small>Ativo: 10.10.0.20</small>','Evidência documental<small>Origem: caso de demonstração</small><small>Localização ilustrativa</small>'][i]}function mapZoom(n){zoom=Math.max(1,Math.min(2.2,zoom+n));$('#mapsvg').style.transform='scale('+zoom+')'}function terminal(){return '<section class="card terminal '+(page==='Terminal'?'fullterminal':'')+'"><div class="cardhead"><h2><span class="green">›_</span> Terminal Linux</h2><small>SIMULADOR LOCAL <button onclick="togglePause()" style="padding:3px 7px;margin-left:8px">'+(paused?'Retomar':'Pausar')+'</button></small></div><div class="terminalbody" id="termout"><pre>NEXO sandbox simulator v0.1\nDigite help para listar os comandos disponíveis.\n\n<span class="prompt">atlas@nexo:~$</span> lab-status\nProjeto: '+esc(project)+'\nEscopo: 3 ativos fictícios • rede 10.10.0.0/24\nStatus: '+(paused?'pausado':'demonstração pronta')+'</pre><form id="terminalform" class="commandline"><label for="cmd" class="prompt">atlas@nexo:~$</label><input id="cmd" autocomplete="off" spellcheck="false" aria-label="Comando do terminal demonstrativo"></form></div></section>'}function togglePause(){paused=!paused;render()}function chat(){return '<section class="card chat"><div class="chathead"><h2><span>✧</span> IA NEXO <span class="pill" style="margin-left:auto">DEMO</span></h2><p>Seu copiloto em segurança digital</p></div><div class="chatcontext">'+esc(project)+'<span>● Contexto local</span></div><div class="messages" id="messages"><div class="bubble"><div class="chatname">ASSISTENTE NEXO</div>Olá, Alex. Vamos organizar sua próxima análise?<br>Posso explicar ferramentas, ajudar com evidências e orientar sua proteção digital.<div class="source">Respostas demonstrativas · sem modelo de IA conectado</div></div></div><div class="suggestions"><button onclick="askPreset(\'Como começo a análise?\')">↗ Como começo a análise?</button><button onclick="askPreset(\'Como organizar evidências?\')">▤ Organizar evidências</button><button onclick="askPreset(\'Como proteger minhas contas?\')">◇ Proteger minhas contas</button></div><form id="chatform" class="chatform"><input id="chatinput" aria-label="Pergunta ao assistente" placeholder="Pergunte à IA NEXO…" maxlength="1500" required><button aria-label="Enviar pergunta">↑</button></form><div class="chatnote">Não insira senhas ou dados pessoais nesta demonstração.</div></section>'}function evidenceCard(){return '<section class="card evidence"><div class="cardhead"><h2>Evidências do caso <span class="pill">'+evidence.length+'</span></h2><button onclick="addEvidence()" style="font-size:10px;padding:6px 9px">＋ Adicionar</button></div>'+evidence.map((e,i)=>'<div class="evidencerow"><span class="purple">▤</span><div style="flex:1"><strong>'+esc(e.name)+'</strong><small>'+esc(e.desc)+'</small></div><span class="pill">'+esc(e.type)+'</span><button onclick="removeEvidence('+i+')" aria-label="Remover '+esc(e.name)+'">✕</button></div>').join('')+(evidence.length?'':'<p class="empty">Nenhuma evidência. Adicione uma nota para começar.</p>')+'</section>'}function addEvidence(){modal('<h1>Adicionar uma nota ao caso</h1><p class="sub">Registre uma observação de demonstração. Ela fica apenas nesta sessão.</p><form id="evform"><label for="evname">Título</label><input id="evname" required maxlength="100" placeholder="Ex.: Observação do inventário"><label for="evdesc">Origem e contexto</label><input id="evdesc" required maxlength="250" placeholder="Descreva de onde veio a informação"><button class="primary">Adicionar ao caso</button></form>');$('#evform').onsubmit=e=>{e.preventDefault();evidence.push({name:$('#evname').value,desc:$('#evdesc').value,type:'Nota'});closeModal();render();toast('Nota adicionada ao caso')}}function removeEvidence(i){evidence.splice(i,1);render();toast('Evidência removida da sessão')}function lab(){let center;if(page==='Visão geral')center='<div class="labgrid"><div>'+tools()+'<div class="card" style="padding:17px;margin-top:18px"><span class="eyebrow">ESCOPO DO PROJETO</span><h2 style="margin:12px 0">'+esc(project)+'</h2><p class="sub">3 ativos fictícios<br>10.10.0.0/24</p><span class="badge">◎ Ambiente isolado planejado</span></div></div><div>'+mapCard()+terminal()+'</div></div>'+evidenceCard();else if(page==='Mapa')center=mapCard()+evidenceCard();else if(page==='Terminal')center=terminal();else if(page==='Ferramentas')center=tools();else if(page==='Evidências')center=evidenceCard();else if(page==='Relatórios')center=reportCard();else center='<section class="card"><div class="cardhead"><h2>Rede e ativos do laboratório</h2><span class="pill">FICTÍCIO</span></div>'+[['Gateway','10.10.0.1'],['Servidor Atlas','10.10.0.10'],['Estação de análise','10.10.0.20']].map(([n,ip])=>'<div class="evidencerow"><span class="green">⌁</span><strong>'+n+'</strong><code>'+ip+'</code><span class="badge">Inventário demo</span></div>').join('')+'</section>'+mapCard();return title(page==='Visão geral'?'Laboratório de cibersegurança':page,'Explore, conecte e transforme informações em decisões.')+(page==='Visão geral'?stats():'')+'<div class="workspacegrid"><div>'+center+'</div>'+chat()+'</div>'}function reportCard(){return '<section class="card actioncard"><span>▧</span><h2>Relatório do '+esc(project)+'</h2><p>Exporte o escopo fictício e as '+evidence.length+' evidências desta sessão em um arquivo de texto. Inclui identificação explícita de demonstração.</p><button class="primary" onclick="downloadReport()">↓ Baixar relatório</button></section>'}function downloadReport(){const text='NEXO — RELATÓRIO DE DEMONSTRAÇÃO\n'+project+'\nGerado em: '+new Date().toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})+' (São Paulo)\n\nNenhuma varredura ou investigação real foi executada.\nAtivos fictícios: 10.10.0.1, 10.10.0.10, 10.10.0.20\n\nEVIDÊNCIAS\n'+evidence.map(e=>e.name+'\nOrigem/contexto: '+e.desc).join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='nexo-relatorio-demo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Relatório exportado')}function setup(){modal('<h1>Prepare seu ambiente</h1><p class="sub">Configure o projeto de demonstração. Um laboratório Linux real será uma integração futura.</p><form id="setupform"><label for="proj">Nome do projeto</label><input id="proj" required maxlength="60" value="'+esc(project)+'"><label for="mission">Missão</label><select id="mission"><option>Análise de rede e ativos</option><option>Organização de investigação OSINT</option><option>Análise de arquivos</option></select><label for="scope">Escopo</label><input id="scope" value="Rede fictícia 10.10.0.0/24" readonly><button class="primary">Abrir ambiente demonstrativo →</button></form>');$('#setupform').onsubmit=e=>{e.preventDefault();project=$('#proj').value;closeModal();paused=false;page='Visão geral';render();toast('Projeto configurado')}}function simple(){let names=role===roles[1]?['Sua segurança, com clareza.','Vamos cuidar da sua vida digital, um passo de cada vez.']:role===roles[2]?['Cada pista, no lugar certo.','Organize seu caso e acompanhe a origem de cada informação.']:['Sua empresa, mais protegida.','Entenda prioridades e organize as próximas ações da equipe.'];const cards=role===roles[1]?[['◇','Proteger minhas contas','Crie senhas únicas e ative a autenticação em duas etapas.','Como proteger minhas contas?'],['↗','Recebi um link suspeito','Entenda os sinais de fraude antes de abrir um endereço.','Como avaliar um link suspeito?'],['▤','Meus dados foram expostos','Receba uma orientação inicial sobre como agir.','O que fazer com dados expostos?']]:role===roles[2]?[['◎','Caso Aurora','Caso fictício para organizar hipóteses, fontes e próximos passos.','Como organizar um caso?'],['▤','Evidências e fontes','Registre a origem e preserve o contexto de cada pista.','Como organizar evidências?'],['▧','Relatório do caso','Reúna o escopo e as notas em um documento.','relatorio']]:[['▦','Inventário de ativos','Conheça os sistemas e responsáveis da sua organização.','Como organizar ativos?'],['◇','Prioridades de segurança','Comece pelas contas, atualizações e cópias de segurança.','Como priorizar riscos?'],['▧','Resumo para a equipe','Exporte as observações registradas nesta sessão.','relatorio']];const center=page==='Evidências'?evidenceCard():page==='Relatórios'?reportCard():'<div class="card welcome"><span class="eyebrow">AMBIENTE ADAPTADO · '+esc(role.toUpperCase())+'</span><h1>'+names[0]+'</h1><p class="sub">'+names[1]+'</p></div><div class="widegrid">'+cards.map(([i,n,d,q])=>'<section class="card actioncard"><span>'+i+'</span><h2>'+n+'</h2><p>'+d+'</p><button onclick="'+(q==='relatorio'?'downloadReport()':'askPreset(\''+q+'\')')+'">Começar →</button></section>').join('')+'</div>'+evidenceCard();return title('Seu espaço de segurança','Uma experiência preparada para você.')+'<div class="workspacegrid"><div>'+center+'</div>'+chat()+'</div>'}function askPreset(t){if(!$('#messages'))return;const m=$('#messages');m.insertAdjacentHTML('beforeend','<div class="bubble userbubble">'+esc(t)+'</div>');let a;if(/nmap/i.test(t))a='O Nmap ajuda a descobrir hosts e serviços de uma rede. Antes de utilizá-lo, defina os ativos e confirme a autorização. Aqui ele aparece apenas como item de catálogo.';else if(/wireshark/i.test(t))a='O Wireshark permite examinar tráfego capturado. Uma análise começa pelo contexto da captura e pelos protocolos envolvidos. Esta demonstração não captura tráfego.';else if(/sherlock/i.test(t))a='O Sherlock consulta a existência de nomes de usuário em serviços públicos. Uma coincidência de nome não comprova identidade. Sempre registre a fonte e confirme a informação por outros meios.';else if(/conta|senha/i.test(t))a='Comece pelas contas de e-mail: use uma senha longa e exclusiva, ative autenticação em duas etapas e revise sessões abertas. Nunca compartilhe senhas ou códigos de recuperação no chat.';else if(/link/i.test(t))a='Confira o domínio e o remetente por outro canal. Para acessar sua conta, abra o aplicativo oficial ou digite o endereço conhecido. Esta versão não verifica links automaticamente.';else if(/expost/i.test(t))a='Identifique quais dados foram expostos e registre a fonte. Troque senhas comprometidas, encerre sessões desconhecidas e ative autenticação em duas etapas. Em caso de fraude financeira, contate sua instituição pelo canal oficial.';else if(/evidência|caso/i.test(t))a='Registre a origem, a data de coleta e o contexto de cada item. Preserve o original, trabalhe em cópias e separe fatos verificados de hipóteses. Você pode adicionar notas na área de evidências e exportá-las no relatório.';else if(/risco|ativo/i.test(t))a='Organize os ativos por responsável e impacto no negócio. Priorize contas com acesso amplo, sistemas expostos e atualizações críticas. Registre ações e responsáveis antes de acompanhar a evolução.';else a='Comece definindo a pergunta da análise e o escopo autorizado. Depois organize os ativos e as fontes disponíveis, registre as observações e revise as conclusões. Neste protótipo, experimente o mapa, as notas de evidência e o relatório.';m.insertAdjacentHTML('beforeend','<div class="bubble"><div class="chatname">NEXO · RESPOSTA DEMONSTRATIVA</div>'+a+'</div>');m.scrollTop=m.scrollHeight}function bind(){if($('#chatform'))$('#chatform').onsubmit=e=>{e.preventDefault();let q=$('#chatinput').value.trim();if(q)askPreset(q);$('#chatinput').value=''};if($('#terminalform'))$('#terminalform').onsubmit=e=>{e.preventDefault();const input=$('#cmd'),cmd=input.value.trim();if(!cmd)return;if(paused){toast('Retome o ambiente para usar o simulador');return}if(cmd==='clear'){[...$('#termout').children].forEach(x=>{if(x.id!=='terminalform')x.remove()});input.value='';return}const answers={'help':'Comandos simulados: help, whoami, ip -br a, lab-status, ls, clear.\nNão há shell real nem acesso à rede.','whoami':'analista-demo','ip -br a':'lo      UNKNOWN  127.0.0.1/8\neth0    UP       10.10.0.10/24 (fictício)','lab-status':'Projeto: '+project+'\nStatus: demonstração local\nAtivos: 3 fictícios','ls':'inventario_atlas.csv  notas-demo.txt'};const pre=document.createElement('pre');pre.textContent='atlas@nexo:~$ '+cmd+'\n'+(answers[cmd]||'Comando indisponível no simulador. Digite help.');$('#termout').insertBefore(pre,$('#terminalform'));input.value='';$('#termout').scrollTop=$('#termout').scrollHeight}}render();if(localStorage.getItem('nexo-signed-out')!=='true'&&!localStorage.getItem('nexo-role'))profiles();

function setAccountMenu(open){$('#accountMenu').hidden=!open;$('#accountBtn').setAttribute('aria-expanded',String(open));$('#profileBtn').setAttribute('aria-expanded',String(open))}
function toggleAccountMenu(){setAccountMenu($('#accountMenu').hidden)}
$('#accountBtn').onclick=toggleAccountMenu;
$('#profileBtn').setAttribute('aria-controls','accountMenu');
$('#profileBtn').setAttribute('aria-expanded','false');
$('#switchProfile').onclick=()=>{setAccountMenu(false);profiles()};
$('#logoutBtn').onclick=logout;
document.addEventListener('click',e=>{if(!e.target.closest('#accountMenu, #accountBtn, #profileBtn'))setAccountMenu(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){setAccountMenu(false);$('#accountBtn').focus()}});
function logout(){setAccountMenu(false);closeModal();localStorage.setItem('nexo-signed-out','true');localStorage.removeItem('nexo-role');role=roles[0];page='Visão geral';project='Projeto Atlas';evidence=[];paused=false;if(typeof globeCleanup==='function'){globeCleanup();globeCleanup=null}$('#content').innerHTML='';showLogin();$('#demoLogin').focus()}
function showLogin(){document.body.classList.add('signed-out');$('#loginScreen').hidden=false;$('#loginScreen').innerHTML='<div class="login-art"><a class="brand" href="#"><span>И</span> NEXO<span class="dot">.</span></a><div class="login-orbit"><span>◎</span></div><div class="eyebrow">INTELIGÊNCIA CONECTADA</div><h1>Seu próximo passo,<br>mais seguro.</h1><p>Proteção, investigação e conhecimento.<br>Um ambiente preparado para cada missão.</p><small>NEXO PLATFORM / PROTÓTIPO PRIVADO</small></div><div class="login-entry"><span class="pill">ACESSO DEMONSTRATIVO</span><h1>Bem-vindo ao NEXO.</h1><p class="sub">Você saiu do ambiente de demonstração.<br>Entre novamente para escolher seu perfil.</p><button id="demoLogin" class="primary" onclick="loginDemo()">Entrar na demonstração →</button><div class="login-disclaimer">Este fluxo controla apenas a interface neste navegador. Não autentica contas reais nem encerra a sessão do ChatGPT usada para acessar o site privado.</div><span class="login-foot">Sem cadastro ou senha nesta etapa.</span></div>'}
function loginDemo(){localStorage.removeItem('nexo-signed-out');render();profiles()}
